@import url("https://fonts.googleapis.com/css2?family=Jost:wght@300..700&display=swap");

ul,ol{list-style:revert;margin:revert;padding:revert}
li{list-style:revert}
img,svg,video{max-width:revert;height:revert;display:revert;vertical-align:revert}
button,input,select,textarea{font:revert;color:revert;background:revert;border:revert;margin:revert;padding:revert;text-align:revert;line-height:revert}
table{border-collapse:revert;text-indent:revert}
blockquote,figure,fieldset{margin:revert;padding:revert}
h1,h2,h3,h4,h5,h6{font-size:revert;font-weight:revert;margin:revert;line-height:revert}
p{margin:revert}
a{color:revert;text-decoration:revert}
hr{border:revert;height:revert;color:revert}

.nifty-part-header-2 .bt-header {--navy:#004877;--ink:#252627;--cream:#fff;--sand:#F3E9D9;--sky:#3C96E7;--line:rgba(0,72,119,.16);--line2:rgba(0,72,119,.08);--mut:rgba(0,72,119,.62);--body:rgba(37,38,39,.78);--serif:"Jost","Century Gothic",Futura,"Helvetica Neue",Arial,sans-serif;--sans:"Jost","Century Gothic",Futura,"Helvetica Neue",Arial,sans-serif;--gut:clamp(20px,4vw,56px);--ease:cubic-bezier(.2,.7,.2,1);--ann:40px;--bar:84px;position:sticky;top:calc(var(--ann) * -1);z-index:900;font-family:var(--sans);font-size:16px;line-height:1.5;color:var(--ink);background:var(--cream);-webkit-font-smoothing:antialiased;text-align:left}
.nifty-part-header-2 .bt-header *, .nifty-part-header-2 .bt-header *::before, .nifty-part-header-2 .bt-header *::after {box-sizing:border-box}
.nifty-part-header-2 .bt-header a {color:inherit;text-decoration:none}
.nifty-part-header-2 .bt-header ul {list-style:none;margin:0;padding:0}
.nifty-part-header-2 .bt-header p {margin:0}
.nifty-part-header-2 .bt-header img {display:block;max-width:100%}
.nifty-part-header-2 .bt-header svg {width:20px;height:20px;flex-shrink:0;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.nifty-part-header-2 .bt-header [hidden] {display:none!important}
.nifty-part-header-2 .bt-header a:focus-visible, .nifty-part-header-2 .bt-header label:focus-visible, .nifty-part-header-2 .bt-header button:focus-visible, .nifty-part-header-2 .bt-header input:focus-visible {outline:2px solid var(--sky);outline-offset:3px}
.nifty-part-header-2 .bt-header .bt-skip {position:absolute;left:12px;top:calc(var(--ann) + 12px);z-index:60;background:var(--navy);color:#fff;padding:12px 18px;font-size:13px;font-weight:500;letter-spacing:.1em;text-transform:uppercase;opacity:0;pointer-events:none;clip-path:inset(50%)}
.nifty-part-header-2 .bt-header .bt-skip:focus {opacity:1;pointer-events:auto;clip-path:none}
.nifty-part-header-2 .bt-header .bt-announce {height:var(--ann);background:var(--navy);color:#fff;display:flex;align-items:center;justify-content:center;font-size:11.5px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;white-space:nowrap;overflow:hidden}
.nifty-part-header-2 .bt-header .bt-ann-track {display:flex;align-items:center}
.nifty-part-header-2 .bt-header .bt-ann-set {display:flex;align-items:center;flex:none}
.nifty-part-header-2 .bt-header .bt-ann-set+.bt-ann-set {display:none}
.nifty-part-header-2 .bt-header .bt-ann-set>span {padding:0 22px;position:relative}
.nifty-part-header-2 .bt-header .bt-ann-set>span+span::before {content:"";position:absolute;left:0;top:50%;width:1px;height:12px;background:rgba(255,255,255,.4);transform:translateY(-50%)}
.nifty-part-header-2 .bt-header .bt-ann-sale {display:inline-flex;align-items:center;gap:9px;height:26px;margin-left:10px;padding:0 14px 0 12px;border-radius:999px;background:var(--cream);color:var(--navy);letter-spacing:.14em;transition:background .4s var(--ease),transform .5s var(--ease)}
.nifty-part-header-2 .bt-header .bt-ann-sale:hover {background:#fff;transform:translateY(-1px)}
.nifty-part-header-2 .bt-header .bt-ann-sale b {font-weight:500;padding-left:9px;border-left:1px solid rgba(0,72,119,.32)}
.nifty-part-header-2 .bt-header .bt-ann-sale i {width:7px;height:7px;background:var(--navy);transform:rotate(45deg);animation:btAnnPulse 2.4s ease-in-out infinite}
@keyframes btAnnPulse {0%,100%{box-shadow:0 0 0 0 rgba(0,72,119,.5)}60%{box-shadow:0 0 0 7px rgba(0,72,119,0)}}
@keyframes btAnnRun {to{transform:translateX(-50%)}}
.nifty-part-header-2 .bt-header .bt-bar {position:relative;display:flex;align-items:center;gap:clamp(16px,2vw,32px);height:var(--bar);padding:0 var(--gut);background:var(--cream);border-bottom:1px solid var(--line)}
