.nifty-part-header-2 .bt-header .bt-nav-head, .nifty-part-header-2 .bt-header .bt-nav-foot, .nifty-part-header-2 .bt-header .bt-sub-lbl, .nifty-part-header-2 .bt-header .bt-act.bt-burger {display:none}
.nifty-part-header-2 .bt-header .bt-menu {display:flex;align-items:stretch;gap:clamp(12px,1.55vw,28px)}
.nifty-part-header-2 .bt-header .bt-item {display:flex;align-items:stretch}
