.nifty-part-header-2 .bt-header .bt-item-special>a {align-self:center;position:relative;overflow:hidden;height:42px;padding:0 18px 0 16px;color:#fff;background:linear-gradient(135deg,#004877 0%,#00365b 60%,#001f36 100%);box-shadow:0 14px 22px -14px rgba(0,54,91,.9);transition:transform .6s var(--ease),box-shadow .6s var(--ease)}
.nifty-part-header-2 .bt-header .bt-item-special>a::before {content:"";width:7px;height:7px;flex:none;background:var(--pale,#AED3F5);transform:rotate(45deg);margin-right:10px;animation:btNavGem 3.2s var(--ease) infinite}
.nifty-part-header-2 .bt-header .bt-item-special>a::after {left:-60%;right:auto;top:0;bottom:0;width:46%;height:auto;background:linear-gradient(100deg,transparent,rgba(255,255,255,.34),transparent);transform:skewX(-18deg);animation:btNavSheen 4.6s ease-in-out infinite}
.nifty-part-header-2 .bt-header .bt-item-special:hover>a, .nifty-part-header-2 .bt-header .bt-item-special:focus-within>a {color:#fff;transform:translateY(-2px);box-shadow:0 20px 26px -14px rgba(0,54,91,1)}
.nifty-part-header-2 .bt-header .bt-item-special:hover>a::after, .nifty-part-header-2 .bt-header .bt-item-special:focus-within>a::after {transform:skewX(-18deg)}
@keyframes btNavSheen {0%,58%{left:-60%}100%{left:130%}}
@keyframes btNavGem {0%,100%{transform:rotate(45deg) scale(1)}50%{transform:rotate(225deg) scale(1.15)}}
@media (prefers-reduced-motion:reduce) {.nifty-part-header-2 .bt-header .bt-item-special>a::before, .nifty-part-header-2 .bt-header .bt-item-special>a::after {animation:none}}
.nifty-part-header-2 .bt-header .bt-mega {position:absolute;left:0;right:0;top:100%;z-index:5;background:var(--cream);border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin-top:-1px;padding:44px var(--gut) 52px;opacity:0;visibility:hidden;transform:translateY(-8px);transition:opacity .4s var(--ease),transform .4s var(--ease),visibility 0s .4s}
.nifty-part-header-2 .bt-header .bt-item:hover>.bt-mega, .nifty-part-header-2 .bt-header .bt-item:focus-within>.bt-mega {opacity:1;visibility:visible;transform:none;transition-delay:.05s,.05s,0s}
.nifty-part-header-2 .bt-header .bt-mega-in {max-width:1320px;margin:0 auto;display:flex;gap:clamp(32px,4vw,72px)}
.nifty-part-header-2 .bt-header .bt-mega-col {flex:1;min-width:0}
.nifty-part-header-2 .bt-header .bt-mega-col-2 ul {columns:2;column-gap:40px}
.nifty-part-header-2 .bt-header .bt-mega-h {font-size:11px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;color:var(--mut);margin:0 0 16px;padding-bottom:14px;border-bottom:1px solid var(--line2)}
.nifty-part-header-2 .bt-header .bt-mega li {break-inside:avoid}
.nifty-part-header-2 .bt-header .bt-mega li a {display:inline-block;font-family:var(--serif);font-weight:500;font-size:20px;line-height:1.3;padding:6px 0;transition:color .3s var(--ease),transform .5s var(--ease)}
