.nifty-part-header-2 .bt-header .bt-mega-all {display:inline-flex;align-items:center;gap:10px;margin-top:22px;font-size:11.5px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;color:var(--navy);border-bottom:1px solid currentColor;padding-bottom:5px}
