.nifty-part-header-2 .bt-header .bt-mega-sale {flex:1;min-width:230px;max-width:300px;margin-left:auto;display:flex;flex-direction:column;justify-content:flex-end;padding:26px 26px 24px;background:linear-gradient(160deg,#004877,#001d33);color:#fff;position:relative;overflow:hidden}
.nifty-part-header-2 .bt-header .bt-mega-sale::before {content:"12";position:absolute;right:-8px;top:-34px;font-family:var(--serif);font-weight:500;font-size:190px;line-height:1;color:rgba(174,211,245,.14)}
.nifty-part-header-2 .bt-header .bt-mega-sale small {position:relative;font-size:10.5px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:#AED3F5}
