/* Category pages: sidebar filter, same design as the Shop page (23 Nov 2026) */
main.bt-catp .sx-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,2.6fr);gap:clamp(20px,2.6vw,44px);align-items:start}
main.bt-catp .sx-ft{position:absolute;width:1px;height:1px;margin:0;opacity:0;pointer-events:none}
main.bt-catp .sx-side{position:sticky;top:96px;min-width:0;max-height:calc(100vh - 116px);overflow-y:auto;overscroll-behavior:contain;padding:2px 14px 2px 2px;scrollbar-width:thin;scrollbar-color:rgba(0,72,119,.3) transparent}
main.bt-catp .sx-side-h{display:none}
main.bt-catp .sx-q{position:relative;margin:0 0 18px}
main.bt-catp .sx-q input{display:block;width:100%;min-width:0;height:52px;margin:0;border:1px solid var(--line);border-radius:2px;background:#fff;padding:0 44px 0 16px;font-family:var(--sans);font-size:16px;line-height:1.2;color:var(--ink);text-align:left;outline:0;-webkit-appearance:none;appearance:none;transition:border-color .3s,box-shadow .3s}
main.bt-catp .sx-q input:focus{border-color:var(--navy);box-shadow:0 0 0 3px rgba(0,72,119,.12)}
main.bt-catp .sx-q input::placeholder{color:var(--mut)}
main.bt-catp .sx-q svg{position:absolute;right:14px;top:17px;width:18px;height:18px;color:var(--navy);fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;pointer-events:none}
main.bt-catp .sx-blk{padding:18px 0;border-top:1px solid var(--line)}
main.bt-catp .sx-blk-h{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:0 0 12px;font-size:11px;line-height:1;font-weight:500;letter-spacing:.22em;text-transform:uppercase;color:var(--mut)}
main.bt-catp .sx-blk .bt-fgroup{display:block;margin:0;padding:0;overflow:visible;max-width:none}
main.bt-catp .sx-blk .bt-fgroup>b{display:none}
main.bt-catp .sx-opt{display:flex;align-items:center;gap:11px;min-height:40px;padding:5px 10px 5px 8px;margin:0 -8px;border:0;border-radius:2px;background:none;font-size:16px;line-height:1.25;color:var(--ink);cursor:pointer;white-space:normal;transform:none;transition:background .3s var(--ease),color .3s var(--ease)}
main.bt-catp .sx-opt:hover{background:rgba(0,72,119,.06);transform:none;border-color:transparent}
main.bt-catp .sx-opt::before{content:"";flex:0 0 auto;width:16px;height:16px;border:1px solid rgba(0,72,119,.5);border-radius:50%;background:#fff;box-shadow:inset 0 0 0 3px #fff;transition:background .3s,border-color .3s}
main.bt-catp .sx-opt.sx-chk::before{border-radius:2px}
main.bt-catp .sx-opt>i:not(.sx-n){display:none}
main.bt-catp .sx-opt .sx-n{margin-left:auto;font-style:normal;font-size:12.5px;color:var(--mut);width:auto;height:auto;border:0;transform:none;background:none}
main.bt-catp .bt-fl:checked+.sx-opt,main.bt-catp .bt-fb:checked+.sx-opt,main.bt-catp .bt-fo:checked+.sx-opt,main.bt-catp .nf-pb:checked+.sx-opt{color:var(--navy);font-weight:500;background:none;border-color:transparent}
main.bt-catp .bt-fl:checked+.sx-opt::before,main.bt-catp .bt-fb:checked+.sx-opt::before,main.bt-catp .bt-fo:checked+.sx-opt::before,main.bt-catp .nf-pb:checked+.sx-opt::before{background:var(--navy);border-color:var(--navy)}
main.bt-catp .bt-fl:focus-visible+.sx-opt,main.bt-catp .bt-fb:focus-visible+.sx-opt,main.bt-catp .bt-fo:focus-visible+.sx-opt,main.bt-catp .nf-pb:focus-visible+.sx-opt{outline:2px solid var(--sky);outline-offset:1px}
main.bt-catp .nf-pb{position:absolute;opacity:0;width:1px;height:1px;margin:0;pointer-events:none}
html:not(.bt-js) main.bt-catp .sx-js{display:none}
main.bt-catp .sx-blk .bt-fsel{display:none;width:100%;flex-direction:column;align-items:stretch;gap:0;font-size:0}
html.bt-js main.bt-catp .sx-blk .bt-fsel{display:flex}
main.bt-catp .sx-blk .bt-fsel select{width:100%;height:46px;font-size:15px}
main.bt-catp .sx-clear{display:inline-flex;align-items:center;gap:8px;margin-top:4px;padding:0 0 4px;border:0;border-bottom:1px solid;background:none;font-family:var(--sans);font-size:11.5px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;color:var(--navy);cursor:pointer}
main.bt-catp .sx-help{margin-top:8px;padding:20px 20px 22px;color:#fff;background:linear-gradient(150deg,#004877,#002a45);border-radius:2px}
main.bt-catp .sx-help small{display:block;font-size:10.5px;font-weight:500;letter-spacing:.22em;text-transform:uppercase;color:#AED3F5}
main.bt-catp .sx-help b{display:block;margin:8px 0 6px;font-family:var(--serif);font-weight:500;font-size:22px;line-height:1.15}
main.bt-catp .sx-help p{font-size:14.5px;line-height:1.5;color:rgba(255,255,255,.84)}
main.bt-catp .sx-help a,main.bt-catp .sx-help label{display:flex;align-items:center;justify-content:center;gap:8px;min-height:44px;margin-top:12px;padding:0 12px;border:1px solid rgba(255,255,255,.6);border-radius:2px;font-size:11px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;text-align:center;color:#fff;cursor:pointer;transition:background .4s var(--ease),color .4s var(--ease)}
main.bt-catp .sx-help a.sx-tel{background:#fff;color:var(--navy);border-color:#fff;letter-spacing:.08em;font-size:14px}
main.bt-catp .sx-help a:hover,main.bt-catp .sx-help label:hover{background:#fff;color:var(--navy)}
main.bt-catp .sx-main{min-width:0}
main.bt-catp .sx-bar{display:flex;flex-wrap:wrap;align-items:center;gap:10px 16px;min-height:52px;margin-bottom:18px;padding-bottom:14px;border-bottom:1px solid var(--line)}
main.bt-catp .sx-count{display:block;font-family:var(--sans);font-size:15px;color:var(--body)}
main.bt-catp .sx-count b{font-family:var(--serif);font-weight:500;font-size:24px;line-height:1;color:var(--navy);margin-right:6px}
main.bt-catp .sx-chips{display:flex;flex-wrap:wrap;gap:6px;flex:1 1 0;min-width:0}
main.bt-catp .sx-chips button{display:inline-flex;align-items:center;gap:8px;min-height:34px;margin:0;padding:0 10px 0 13px;border:1px solid var(--line);border-radius:999px;background:#fff;font-family:var(--sans);font-size:13.5px;line-height:1;color:var(--ink);cursor:pointer;transition:border-color .3s,background .3s}
main.bt-catp .sx-chips button:hover{border-color:var(--navy);background:rgba(0,72,119,.06)}
main.bt-catp .sx-chips button::after{content:"";width:9px;height:9px;background:linear-gradient(45deg,transparent 44%,currentColor 44%,currentColor 56%,transparent 56%),linear-gradient(-45deg,transparent 44%,currentColor 44%,currentColor 56%,transparent 56%)}
main.bt-catp .sx-sort{display:flex;align-items:center;gap:10px;margin-left:auto;font-size:11px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--mut)}
main.bt-catp .sx-sort select{height:44px;margin:0;border:1px solid var(--line);border-radius:2px;background-color:#fff;padding:0 34px 0 12px;font-family:var(--sans);font-size:15px;line-height:1.2;letter-spacing:0;text-transform:none;color:var(--ink);cursor:pointer;-webkit-appearance:none;appearance:none;background-image:linear-gradient(45deg,transparent 50%,#004877 50%),linear-gradient(135deg,#004877 50%,transparent 50%);background-position:calc(100% - 17px) 19px,calc(100% - 12px) 19px;background-size:5px 5px;background-repeat:no-repeat}
html:not(.bt-js) main.bt-catp .sx-sort{display:none}
main.bt-catp .sx-fbtn,main.bt-catp .sx-scrim,main.bt-catp .sx-done{display:none}
main.bt-catp .sx-main .bt-pgrid{grid-template-columns:repeat(3,minmax(0,1fr))}
@media (max-width:1279px){
main.bt-catp .sx-layout{grid-template-columns:minmax(0,1fr) minmax(0,2.2fr)}
main.bt-catp .sx-main .bt-pgrid{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media (max-width:1023px){
main.bt-catp .sx-layout{grid-template-columns:minmax(0,1fr)}
main.bt-catp .sx-main .bt-pgrid{grid-template-columns:repeat(3,minmax(0,1fr))}
main.bt-catp .sx-side{position:fixed;z-index:960;left:0;top:0;bottom:0;width:min(400px,90vw);max-height:none;padding:0 20px 24px;background:#fff;box-shadow:30px 0 60px -30px rgba(0,0,0,.5);clip-path:inset(0 100% 0 0);visibility:hidden;transform:translateX(-24px);transition:clip-path .6s var(--ease),transform .6s var(--ease),visibility 0s linear .6s}
main.bt-catp .sx-ft:checked~.sx-side{clip-path:inset(0 -80px 0 0);visibility:visible;transform:none;transition:clip-path .6s var(--ease),transform .6s var(--ease),visibility 0s}
main.bt-catp .sx-scrim{display:block;position:fixed;z-index:950;inset:0;background:rgba(17,18,19,.6);opacity:0;visibility:hidden;transition:opacity .5s var(--ease),visibility 0s linear .5s;cursor:pointer}
main.bt-catp .sx-ft:checked~.sx-scrim{opacity:1;visibility:visible;transition:opacity .5s var(--ease),visibility 0s}
html:has(main.bt-catp .sx-ft:checked){overflow:hidden}
main.bt-catp .sx-side-h{display:flex;align-items:center;justify-content:space-between;position:sticky;top:0;z-index:2;margin:0 -20px 16px;padding:0 20px;height:62px;background:#fff;border-bottom:1px solid var(--line);font-family:var(--serif);font-weight:500;font-size:22px;color:var(--ink)}
main.bt-catp .sx-side-h label{display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;margin-right:-10px;cursor:pointer;color:var(--ink)}
main.bt-catp .sx-side-h svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round}
main.bt-catp .sx-fbtn{display:inline-flex;align-items:center;gap:10px;min-height:44px;padding:0 16px;border:1px solid var(--navy);border-radius:2px;background:var(--navy);color:#fff;font-size:11.5px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;cursor:pointer}
main.bt-catp .sx-fbtn svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round}
main.bt-catp .sx-ft:focus-visible~.sx-main .sx-fbtn{outline:2px solid var(--sky);outline-offset:2px}
main.bt-catp .sx-bar{position:sticky;top:68px;z-index:5;margin:0 calc(var(--gut) * -1) 16px;padding:10px var(--gut);background:rgba(255,255,255,.96);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px)}
main.bt-catp .sx-chips{order:5;flex:1 1 100%}
main.bt-catp .sx-chips:empty{display:none}
main.bt-catp .sx-done{display:flex;position:sticky;bottom:-24px;z-index:2;margin:18px -20px 0;padding:14px 20px;background:#fff;border-top:1px solid var(--line)}
main.bt-catp .sx-done label{flex:1;cursor:pointer}
}
@media (max-width:760px){
main.bt-catp .sx-bar{top:62px}
main.bt-catp .sx-main .bt-pgrid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
main.bt-catp .sx-sort span{display:none}
main.bt-catp .sx-sort select{height:44px;max-width:150px}
main.bt-catp .sx-count b{font-size:20px}
main.bt-catp .sx-count{font-size:14px}
main.bt-catp .sx-bar{gap:10px 10px}
main.bt-catp .sx-fbtn{padding:0 12px;gap:7px;letter-spacing:.1em}
main.bt-catp .sx-sort select{max-width:116px;padding-right:30px}
}

/* Clearance page v2: Car Park Sale (23 Nov 2026) */
main.nf-cps{--red:#E3171B;--gold:#FFD21A;--deep:#00253f}
main.nf-cps .cps-hero{position:relative;overflow:hidden;color:#fff;background:radial-gradient(120% 90% at 78% 8%,#0b639c 0%,#004877 38%,#002a45 78%,#001a2c 100%);padding:clamp(18px,2.4vw,34px) 0 clamp(44px,5vw,80px)}
main.nf-cps .cps-floor{position:absolute;left:-30%;right:-30%;bottom:-4%;height:58%;transform-origin:50% 100%;transform:perspective(900px) rotateX(64deg);background-image:linear-gradient(rgba(174,211,245,.18) 1px,transparent 1px),linear-gradient(90deg,rgba(174,211,245,.18) 1px,transparent 1px);background-size:84px 84px;-webkit-mask-image:linear-gradient(transparent 4%,#000 62%);mask-image:linear-gradient(transparent 4%,#000 62%);animation:cpsFloor 9s linear infinite;pointer-events:none}
main.nf-cps .cps-glow{position:absolute;right:4%;top:-6%;width:52vw;max-width:820px;aspect-ratio:1;border-radius:50%;background:radial-gradient(closest-side,rgba(60,150,231,.45),rgba(60,150,231,0));pointer-events:none;animation:cpsGlow 6s ease-in-out infinite alternate}
@keyframes cpsFloor{to{background-position:0 84px,0 0}}
@keyframes cpsGlow{to{transform:translate(-6%,8%) scale(1.08);opacity:.8}}
main.nf-cps .cps-hero-in{position:relative;z-index:1}
main.nf-cps .cps-crumbs{color:rgba(174,211,245,.8);margin-bottom:clamp(14px,1.8vw,22px)}
main.nf-cps .cps-crumbs a:hover{color:#fff}
main.nf-cps .cps-banner{position:relative;max-width:1320px;margin:0 auto;border-radius:6px;overflow:hidden;box-shadow:0 50px 90px -40px rgba(0,0,0,.75),0 0 0 1px rgba(174,211,245,.25);transform-origin:50% 100%;animation:cpsRise 1.1s var(--ease) both}
main.nf-cps .cps-banner img{display:block;width:100%;height:auto}
main.nf-cps .cps-shine{position:absolute;inset:0;z-index:2;pointer-events:none;background:linear-gradient(105deg,transparent 35%,rgba(255,255,255,.38) 48%,transparent 60%);transform:translateX(-120%);animation:cpsShine 4.8s ease-in-out 1.2s infinite}
main.nf-cps .cps-sticker{position:absolute;z-index:3;right:clamp(10px,2.4vw,34px);top:clamp(10px,2.4vw,34px);display:flex;flex-direction:column;align-items:center;justify-content:center;width:clamp(78px,9vw,124px);aspect-ratio:1;border-radius:50%;background:var(--red);color:#fff;font-size:clamp(11px,1.05vw,14px);font-weight:500;letter-spacing:.12em;text-transform:uppercase;line-height:1.1;box-shadow:0 16px 30px -12px rgba(0,0,0,.6),inset 0 0 0 4px rgba(255,255,255,.25);transform:rotate(-12deg);animation:cpsWobble 2.6s ease-in-out infinite}
main.nf-cps .cps-sticker b{font-size:clamp(22px,2.6vw,36px);letter-spacing:.04em;font-weight:700}
@keyframes cpsRise{from{opacity:0;transform:perspective(1400px) translateY(60px) rotateX(18deg) scale(.96)}to{opacity:1;transform:none}}
@keyframes cpsShine{0%{transform:translateX(-120%)}55%,100%{transform:translateX(120%)}}
@keyframes cpsWobble{0%,100%{transform:rotate(-12deg) scale(1)}50%{transform:rotate(-6deg) scale(1.08)}}
main.nf-cps .cps-copy{max-width:1100px;margin:clamp(28px,3.4vw,52px) auto 0;text-align:center}
main.nf-cps .cps-kicker{display:inline-flex;align-items:center;gap:12px;padding:8px 18px;border-radius:999px;background:var(--red);font-size:12.5px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;animation:cpsPulse 2.2s ease-in-out infinite}
main.nf-cps .cps-kicker i{width:8px;height:8px;background:#fff;transform:rotate(45deg)}
@keyframes cpsPulse{0%,100%{box-shadow:0 0 0 0 rgba(227,23,27,.55)}60%{box-shadow:0 0 0 14px rgba(227,23,27,0)}}
main.nf-cps h1{font-family:var(--serif);font-weight:600;font-size:clamp(36px,5.4vw,80px);line-height:1.02;letter-spacing:-.01em;margin:22px 0 18px;color:#fff}
main.nf-cps h1 em{display:block;font-style:normal;color:var(--gold);text-shadow:0 10px 40px rgba(255,210,26,.35)}
main.nf-cps .cps-lead{max-width:760px;margin:0 auto;font-size:clamp(16.5px,1.4vw,19px);line-height:1.6;color:rgba(255,255,255,.86)}
main.nf-cps .cps-facts{list-style:none;margin:clamp(26px,3vw,42px) 0 0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
main.nf-cps .cps-facts li{display:flex;align-items:center;gap:14px;padding:16px 18px;text-align:left;border:1px solid rgba(174,211,245,.28);border-radius:4px;background:rgba(255,255,255,.06);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);animation:cpsPop .7s var(--ease) both;animation-delay:calc(.5s + var(--d) * .12s)}
main.nf-cps .cps-facts svg{flex:none;width:30px;height:30px;fill:none;stroke:var(--pale);stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
main.nf-cps .cps-facts span{display:flex;flex-direction:column;font-size:13.5px;line-height:1.35;color:rgba(255,255,255,.72)}
main.nf-cps .cps-facts b{font-size:17px;font-weight:500;color:#fff}
main.nf-cps .cps-facts .cps-hot{background:var(--gold);border-color:var(--gold)}
main.nf-cps .cps-facts .cps-hot svg{stroke:var(--deep)}
main.nf-cps .cps-facts .cps-hot span,main.nf-cps .cps-facts .cps-hot b{color:var(--deep)}
@keyframes cpsPop{from{opacity:0;transform:translateY(18px) scale(.94)}to{opacity:1;transform:none}}
main.nf-cps .cps-count{margin:clamp(24px,2.6vw,36px) auto 0}
main.nf-cps .cps-count-h{font-size:12px;font-weight:500;letter-spacing:.22em;text-transform:uppercase;color:var(--pale)}
main.nf-cps .cps-clock{display:flex;justify-content:center;gap:10px;margin-top:12px}
main.nf-cps .cps-clock span{display:flex;flex-direction:column;align-items:center;min-width:clamp(64px,7vw,92px);padding:12px 6px 10px;border-radius:4px;background:#fff;color:var(--mut);font-size:11px;letter-spacing:.16em;text-transform:uppercase;box-shadow:0 16px 30px -18px rgba(0,0,0,.7)}
main.nf-cps .cps-clock b{font-family:var(--serif);font-size:clamp(28px,3.2vw,44px);font-weight:600;line-height:1;color:var(--navy);font-variant-numeric:tabular-nums}
main.nf-cps .cps-over{max-width:640px;margin:26px auto 0;padding:14px 18px;border:1px solid rgba(174,211,245,.4);border-radius:4px;color:#fff}
main.nf-cps .cps-cta{display:flex;flex-wrap:wrap;justify-content:center;gap:12px;margin-top:clamp(24px,2.6vw,36px)}
main.nf-cps .cps-cta svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
main.nf-cps .bt-btn.cps-btn-hot{background:var(--gold);border-color:var(--gold);color:var(--deep);font-weight:600;box-shadow:0 14px 30px -14px rgba(255,210,26,.8);animation:cpsNudge 3s ease-in-out 2s infinite}
main.nf-cps .bt-btn.cps-btn-hot:hover{background:#fff;border-color:#fff;color:var(--navy)}
@keyframes cpsNudge{0%,86%,100%{transform:none}90%{transform:translateY(-4px)}94%{transform:translateY(0)}97%{transform:translateY(-2px)}}
main.nf-cps .cps-addr{display:inline-flex;align-items:center;gap:8px;margin-top:20px;font-size:14.5px;color:rgba(255,255,255,.78)}
main.nf-cps .cps-addr svg{width:18px;height:18px;fill:none;stroke:var(--pale);stroke-width:1.6}
main.nf-cps .cps-ticker{overflow:hidden;background:var(--red);color:#fff;border-top:3px solid var(--gold);border-bottom:3px solid var(--gold)}
main.nf-cps .cps-track{display:flex;width:max-content;animation:cpsRun 34s linear infinite}
main.nf-cps .cps-track p{display:flex;align-items:center;gap:22px;padding:15px 11px;white-space:nowrap;font-size:clamp(14px,1.3vw,17px);font-weight:600;letter-spacing:.16em;text-transform:uppercase}
main.nf-cps .cps-track i{width:9px;height:9px;background:var(--gold);transform:rotate(45deg);flex:none}
@keyframes cpsRun{to{transform:translateX(-50%)}}
main.nf-cps .cps-tiles{padding:clamp(56px,6vw,100px) 0}
main.nf-cps .cps-head{max-width:820px}
main.nf-cps .cps-head-c{margin:0 auto;text-align:center}
main.nf-cps .cps-head h2,main.nf-cps .cps-why h2{font-family:var(--serif);font-weight:500;font-size:clamp(30px,3.6vw,50px);line-height:1.08;color:var(--ink);margin:10px 0 16px}
main.nf-cps .cps-head h2 em,main.nf-cps .cps-why h2 em{font-style:normal;color:var(--navy)}
main.nf-cps .cps-head p{color:var(--body)}
main.nf-cps .cps-r{position:absolute;opacity:0;width:1px;height:1px;margin:0;pointer-events:none}
main.nf-cps .cps-chips{display:flex;flex-wrap:wrap;gap:8px;margin:28px 0 24px}
main.nf-cps .cps-chip{display:inline-flex;align-items:center;gap:10px;min-height:44px;padding:0 18px;border:1px solid var(--line);border-radius:999px;background:#fff;font-size:15px;cursor:pointer;transition:background .4s var(--ease),color .4s var(--ease),border-color .4s var(--ease),transform .4s var(--ease)}
main.nf-cps .cps-chip i{font-style:normal;font-size:12px;color:var(--mut)}
main.nf-cps .cps-chip:hover{border-color:var(--navy);transform:translateY(-2px)}
main.nf-cps .cps-r:checked+.cps-chip{background:var(--navy);border-color:var(--navy);color:#fff}
main.nf-cps .cps-r:checked+.cps-chip i{color:var(--pale)}
main.nf-cps .cps-r:focus-visible+.cps-chip{outline:2px solid var(--sky);outline-offset:2px}
