.bt-header .bt-bf-nav{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:18px 34px 30px}
.bt-header .bt-bf-back,.bt-header .bt-bf-next,.bt-header .bt-bf-send{display:none;align-items:center;justify-content:center;gap:10px;min-height:52px;font-family:var(--sans);font-size:12px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;cursor:pointer;border-radius:2px}
.bt-header .bt-bf-back{padding:0 4px;color:rgba(255,255,255,.8);border:0;background:none}
.bt-header .bt-bf-back svg{width:14px;height:14px;transform:rotate(180deg)}
.bt-header .bt-bf-back:hover{color:#fff}
.bt-header .bt-bf-next,.bt-header .bt-bf-send{margin-left:auto;padding:0 28px;background:var(--cream);color:var(--navy);border:1px solid var(--cream);transition:background .45s var(--ease),color .45s var(--ease),gap .45s var(--ease)}
