.bt-header .bt-bf-next:hover,.bt-header .bt-bf-send:hover{background:transparent;color:#fff;gap:16px}
.bt-header .bt-bs1:checked~.bt-bf .bt-n1,.bt-header .bt-bs2:checked~.bt-bf .bt-n2,.bt-header .bt-bs3:checked~.bt-bf .bt-n3,.bt-header .bt-bs4:checked~.bt-bf .bt-n4{display:inline-flex}
