main.bt-catp .sx-blk-h{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:0 0 12px;font-size:11px;line-height:1;font-weight:500;letter-spacing:.22em;text-transform:uppercase;color:var(--mut)}
main.bt-catp .sx-blk .bt-fgroup{display:block;margin:0;padding:0;overflow:visible;max-width:none}
main.bt-catp .sx-blk .bt-fgroup>b{display:none}
main.bt-catp .sx-opt{display:flex;align-items:center;gap:11px;min-height:40px;padding:5px 10px 5px 8px;margin:0 -8px;border:0;border-radius:2px;background:none;font-size:16px;line-height:1.25;color:var(--ink);cursor:pointer;white-space:normal;transform:none;transition:background .3s var(--ease),color .3s var(--ease)}
main.bt-catp .sx-opt:hover{background:rgba(0,72,119,.06);transform:none;border-color:transparent}
main.bt-catp .sx-opt::before{content:"";flex:0 0 auto;width:16px;height:16px;border:1px solid rgba(0,72,119,.5);border-radius:50%;background:#fff;box-shadow:inset 0 0 0 3px #fff;transition:background .3s,border-color .3s}
main.bt-catp .sx-opt.sx-chk::before{border-radius:2px}
main.bt-catp .sx-opt>i:not(.sx-n){display:none}
main.bt-catp .sx-opt .sx-n{margin-left:auto;font-style:normal;font-size:12.5px;color:var(--mut);width:auto;height:auto;border:0;transform:none;background:none}
main.bt-catp .bt-fl:checked+.sx-opt,main.bt-catp .bt-fb:checked+.sx-opt,main.bt-catp .bt-fo:checked+.sx-opt,main.bt-catp .nf-pb:checked+.sx-opt{color:var(--navy);font-weight:500;background:none;border-color:transparent}
