main.bt-catp .bt-fl:focus-visible+.sx-opt,main.bt-catp .bt-fb:focus-visible+.sx-opt,main.bt-catp .bt-fo:focus-visible+.sx-opt,main.bt-catp .nf-pb:focus-visible+.sx-opt{outline:2px solid var(--sky);outline-offset:1px}
main.bt-catp .nf-pb{position:absolute;opacity:0;width:1px;height:1px;margin:0;pointer-events:none}
html:not(.bt-js) main.bt-catp .sx-js{display:none}
main.bt-catp .sx-blk .bt-fsel{display:none;width:100%;flex-direction:column;align-items:stretch;gap:0;font-size:0}
html.bt-js main.bt-catp .sx-blk .bt-fsel{display:flex}
main.bt-catp .sx-blk .bt-fsel select{width:100%;height:46px;font-size:15px}
main.bt-catp .sx-clear{display:inline-flex;align-items:center;gap:8px;margin-top:4px;padding:0 0 4px;border:0;border-bottom:1px solid;background:none;font-family:var(--sans);font-size:11.5px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;color:var(--navy);cursor:pointer}
main.bt-catp .sx-help{margin-top:8px;padding:20px 20px 22px;color:#fff;background:linear-gradient(150deg,#004877,#002a45);border-radius:2px}
main.bt-catp .sx-help small{display:block;font-size:10.5px;font-weight:500;letter-spacing:.22em;text-transform:uppercase;color:#AED3F5}
main.bt-catp .sx-help b{display:block;margin:8px 0 6px;font-family:var(--serif);font-weight:500;font-size:22px;line-height:1.15}
main.bt-catp .sx-help p{font-size:14.5px;line-height:1.5;color:rgba(255,255,255,.84)}
main.bt-catp .sx-help a,main.bt-catp .sx-help label{display:flex;align-items:center;justify-content:center;gap:8px;min-height:44px;margin-top:12px;padding:0 12px;border:1px solid rgba(255,255,255,.6);border-radius:2px;font-size:11px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;text-align:center;color:#fff;cursor:pointer;transition:background .4s var(--ease),color .4s var(--ease)}
main.bt-catp .sx-help a.sx-tel{background:#fff;color:var(--navy);border-color:#fff;letter-spacing:.08em;font-size:14px}
main.bt-catp .sx-help a:hover,main.bt-catp .sx-help label:hover{background:#fff;color:var(--navy)}
main.bt-catp .sx-main{min-width:0}
main.bt-catp .sx-bar{display:flex;flex-wrap:wrap;align-items:center;gap:10px 16px;min-height:52px;margin-bottom:18px;padding-bottom:14px;border-bottom:1px solid var(--line)}
main.bt-catp .sx-count{display:block;font-family:var(--sans);font-size:15px;color:var(--body)}
main.bt-catp .sx-count b{font-family:var(--serif);font-weight:500;font-size:24px;line-height:1;color:var(--navy);margin-right:6px}
main.bt-catp .sx-chips{display:flex;flex-wrap:wrap;gap:6px;flex:1 1 0;min-width:0}
main.bt-catp .sx-chips button{display:inline-flex;align-items:center;gap:8px;min-height:34px;margin:0;padding:0 10px 0 13px;border:1px solid var(--line);border-radius:999px;background:#fff;font-family:var(--sans);font-size:13.5px;line-height:1;color:var(--ink);cursor:pointer;transition:border-color .3s,background .3s}
main.bt-catp .sx-chips button:hover{border-color:var(--navy);background:rgba(0,72,119,.06)}
main.bt-catp .sx-chips button::after{content:"";width:9px;height:9px;background:linear-gradient(45deg,transparent 44%,currentColor 44%,currentColor 56%,transparent 56%),linear-gradient(-45deg,transparent 44%,currentColor 44%,currentColor 56%,transparent 56%)}
main.bt-catp .sx-sort{display:flex;align-items:center;gap:10px;margin-left:auto;font-size:11px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--mut)}
main.bt-catp .sx-sort select{height:44px;margin:0;border:1px solid var(--line);border-radius:2px;background-color:#fff;padding:0 34px 0 12px;font-family:var(--sans);font-size:15px;line-height:1.2;letter-spacing:0;text-transform:none;color:var(--ink);cursor:pointer;-webkit-appearance:none;appearance:none;background-image:linear-gradient(45deg,transparent 50%,#004877 50%),linear-gradient(135deg,#004877 50%,transparent 50%);background-position:calc(100% - 17px) 19px,calc(100% - 12px) 19px;background-size:5px 5px;background-repeat:no-repeat}
html:not(.bt-js) main.bt-catp .sx-sort{display:none}
main.bt-catp .sx-fbtn,main.bt-catp .sx-scrim,main.bt-catp .sx-done{display:none}
main.bt-catp .sx-main .bt-pgrid{grid-template-columns:repeat(3,minmax(0,1fr))}
@media (max-width:1279px){
main.bt-catp .sx-layout{grid-template-columns:minmax(0,1fr) minmax(0,2.2fr)}
