main.bt-catp .sx-bar{position:sticky;top:68px;z-index:5;margin:0 calc(var(--gut) * -1) 16px;padding:10px var(--gut);background:rgba(255,255,255,.96);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px)}
