main.bt-catp .sx-opt::before{content:"";flex:0 0 auto;width:16px;height:16px;border:1px solid rgba(0,72,119,.5);border-radius:50%;background:#fff;box-shadow:inset 0 0 0 3px #fff;transition:background .3s,border-color .3s}
