main.bt-catp .bt-fl:checked+.sx-opt,main.bt-catp .bt-fb:checked+.sx-opt,main.bt-catp .bt-fo:checked+.sx-opt,main.bt-catp .nf-pb:checked+.sx-opt{color:var(--navy);font-weight:500;background:none;border-color:transparent}
