main.bt-catp .nf-pb{position:absolute;opacity:0;width:1px;height:1px;margin:0;pointer-events:none}
html:not(.bt-js) main.bt-catp .sx-js{display:none}
main.bt-catp .sx-blk .bt-fsel{display:none;width:100%;flex-direction:column;align-items:stretch;gap:0;font-size:0}
