/* Clearance page v2: Car Park Sale (23 Nov 2026) */
main.nf-cps{--red:#E3171B;--gold:#FFD21A;--deep:#00253f}
main.nf-cps .cps-hero{position:relative;overflow:hidden;color:#fff;background:radial-gradient(120% 90% at 78% 8%,#0b639c 0%,#004877 38%,#002a45 78%,#001a2c 100%);padding:clamp(18px,2.4vw,34px) 0 clamp(44px,5vw,80px)}
main.nf-cps .cps-floor{position:absolute;left:-30%;right:-30%;bottom:-4%;height:58%;transform-origin:50% 100%;transform:perspective(900px) rotateX(64deg);background-image:linear-gradient(rgba(174,211,245,.18) 1px,transparent 1px),linear-gradient(90deg,rgba(174,211,245,.18) 1px,transparent 1px);background-size:84px 84px;-webkit-mask-image:linear-gradient(transparent 4%,#000 62%);mask-image:linear-gradient(transparent 4%,#000 62%);animation:cpsFloor 9s linear infinite;pointer-events:none}
main.nf-cps .cps-glow{position:absolute;right:4%;top:-6%;width:52vw;max-width:820px;aspect-ratio:1;border-radius:50%;background:radial-gradient(closest-side,rgba(60,150,231,.45),rgba(60,150,231,0));pointer-events:none;animation:cpsGlow 6s ease-in-out infinite alternate}
@keyframes cpsFloor{to{background-position:0 84px,0 0}}
@keyframes cpsGlow{to{transform:translate(-6%,8%) scale(1.08);opacity:.8}}
main.nf-cps .cps-hero-in{position:relative;z-index:1}
main.nf-cps .cps-crumbs{color:rgba(174,211,245,.8);margin-bottom:clamp(14px,1.8vw,22px)}
main.nf-cps .cps-crumbs a:hover{color:#fff}
main.nf-cps .cps-banner{position:relative;max-width:1320px;margin:0 auto;border-radius:6px;overflow:hidden;box-shadow:0 50px 90px -40px rgba(0,0,0,.75),0 0 0 1px rgba(174,211,245,.25);transform-origin:50% 100%;animation:cpsRise 1.1s var(--ease) both}
main.nf-cps .cps-banner img{display:block;width:100%;height:auto}
main.nf-cps .cps-shine{position:absolute;inset:0;z-index:2;pointer-events:none;background:linear-gradient(105deg,transparent 35%,rgba(255,255,255,.38) 48%,transparent 60%);transform:translateX(-120%);animation:cpsShine 4.8s ease-in-out 1.2s infinite}
main.nf-cps .cps-sticker{position:absolute;z-index:3;right:clamp(10px,2.4vw,34px);top:clamp(10px,2.4vw,34px);display:flex;flex-direction:column;align-items:center;justify-content:center;width:clamp(78px,9vw,124px);aspect-ratio:1;border-radius:50%;background:var(--red);color:#fff;font-size:clamp(11px,1.05vw,14px);font-weight:500;letter-spacing:.12em;text-transform:uppercase;line-height:1.1;box-shadow:0 16px 30px -12px rgba(0,0,0,.6),inset 0 0 0 4px rgba(255,255,255,.25);transform:rotate(-12deg);animation:cpsWobble 2.6s ease-in-out infinite}
main.nf-cps .cps-sticker b{font-size:clamp(22px,2.6vw,36px);letter-spacing:.04em;font-weight:700}
@keyframes cpsRise{from{opacity:0;transform:perspective(1400px) translateY(60px) rotateX(18deg) scale(.96)}to{opacity:1;transform:none}}
@keyframes cpsShine{0%{transform:translateX(-120%)}55%,100%{transform:translateX(120%)}}
@keyframes cpsWobble{0%,100%{transform:rotate(-12deg) scale(1)}50%{transform:rotate(-6deg) scale(1.08)}}
main.nf-cps .cps-copy{max-width:1100px;margin:clamp(28px,3.4vw,52px) auto 0;text-align:center}
main.nf-cps .cps-kicker{display:inline-flex;align-items:center;gap:12px;padding:8px 18px;border-radius:999px;background:var(--red);font-size:12.5px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;animation:cpsPulse 2.2s ease-in-out infinite}
main.nf-cps .cps-kicker i{width:8px;height:8px;background:#fff;transform:rotate(45deg)}
@keyframes cpsPulse{0%,100%{box-shadow:0 0 0 0 rgba(227,23,27,.55)}60%{box-shadow:0 0 0 14px rgba(227,23,27,0)}}
main.nf-cps h1{font-family:var(--serif);font-weight:600;font-size:clamp(36px,5.4vw,80px);line-height:1.02;letter-spacing:-.01em;margin:22px 0 18px;color:#fff}
main.nf-cps h1 em{display:block;font-style:normal;color:var(--gold);text-shadow:0 10px 40px rgba(255,210,26,.35)}
